//! Kanji Pad: draw kana or kanji strokes, see live candidates, click to copy to clipboard.

use eframe::egui;
use kanji_pad::db::{KanjiDb, read_db};
use kanji_pad::engine::{Pt, ScriptMask, recognize};

/// Stroke dataset generated by `cargo run --bin gen`.
const DB_BYTES: &[u8] = include_bytes!("../assets/kanji.kvpd");

/// Candidates kept for incremental narrowing after each stroke.
const POOL_LIMIT: usize = 400;
/// Candidates shown in the UI.
const SHOW_LIMIT: usize = 24;
/// Minimum distance (px) between captured points of a stroke.
const MIN_STEP: f32 = 2.0;
/// Opacity of the ghost overlay showing the best guess.
const GHOST_ALPHA: u8 = 70;
/// Edge length of a square candidate button.
const SQUARE: f32 = 44.0;
/// Edge length of the undo/clear icon buttons.
const ICON: f32 = 26.0;
/// Edge length of the drawing square.
const CANVAS: f32 = 300.0;

struct App {
    db: KanjiDb,
    /// Finished strokes, in normalized canvas space (0..1 of the square).
    strokes: Vec<Vec<Pt>>,
    /// Stroke currently being drawn.
    current: Vec<Pt>,
    /// Ranked candidates from the last completed stroke.
    pool: Vec<kanji_pad::engine::Candidate>,
    /// Text composed from clicked suggestions, shown in the top input so a
    /// whole group can be copied at once.
    buffer: String,
    clipboard: Option<arboard::Clipboard>,
    font_loaded: bool,
}

impl App {
    fn new(cc: &eframe::CreationContext<'_>) -> Self {
        let font_loaded = setup_fonts(&cc.egui_ctx);
        let db = match read_db(DB_BYTES) {
            Ok(db) => db,
            Err(e) => panic!("failed to load stroke database: {e}"),
        };
        Self {
            db,
            strokes: Vec::new(),
            current: Vec::new(),
            pool: Vec::new(),
            buffer: String::new(),
            clipboard: arboard::Clipboard::new().ok(),
            font_loaded,
        }
    }

    fn recompute(&mut self) {
        // Narrow against the previous pool only when there is one; an empty
        // pool means this is the first stroke (or nothing matched), so match
        // from scratch rather than filtering every character out.
        let prev = if self.pool.is_empty() {
            None
        } else {
            Some(self.pool.as_slice())
        };
        self.pool = recognize(&self.strokes, &self.db, prev, ScriptMask::ALL, POOL_LIMIT);
    }

    /// Re-recognize from scratch, e.g. after undo.
    fn refresh(&mut self) {
        self.pool = if self.strokes.is_empty() {
            Vec::new()
        } else {
            recognize(&self.strokes, &self.db, None, ScriptMask::ALL, POOL_LIMIT)
        };
    }

    fn copy_to_clipboard(&mut self, ch: char) {
        if let Some(cb) = &mut self.clipboard {
            let _ = cb.set_text(ch.to_string());
        }
    }
}

/// Map a pointer position to normalized 0..1 canvas space, clamped into the
/// canvas so strokes that leave the square stay on it.
fn clamp_to_canvas(pos: egui::Pos2, rect: egui::Rect, side: f32) -> Pt {
    let x = ((pos.x - rect.min.x) / side).clamp(0.0, 1.0);
    let y = ((pos.y - rect.min.y) / side).clamp(0.0, 1.0);
    (x, y)
}

/// A button icon painted in the widget's text color.
fn icon_atom(
    size: f32,
    draw: impl Fn(&egui::Ui, egui::Rect, egui::Color32) + 'static,
) -> egui::Atom<'static> {
    egui::Atom::paint(egui::vec2(size, size), move |ui, args| draw(ui, args.rect, args.fallback_text_color))
}

/// Undo: a clockwise arc open on the left, with an arrowhead at its top-left
/// end pointing back along the path.
fn undo_icon(size: f32) -> egui::Atom<'static> {
    icon_atom(size, |ui, rect, color| {
        let c = rect.center();
        let r = rect.height() * 0.32;
        let stroke = egui::Stroke::new(1.5, color);
        // Arc from 110deg down through 0deg (right side) to -70deg, y-down.
        let mut arc = Vec::new();
        let mut t = 110.0f32;
        while t >= -70.0 {
            let rad = t.to_radians();
            arc.push(egui::pos2(c.x + r * rad.cos(), c.y - r * rad.sin()));
            t -= 10.0;
        }
        let tip = arc[0];
        ui.painter().line(arc, stroke);
        // Arrowhead at the arc start pointing counterclockwise (undo). The arc
        // travels clockwise, so travel direction at angle s (y-down) is
        // (sin s, cos s); the head points opposite that, and its wings spread
        // backward along the arc — i.e. rotated around the travel direction.
        let s = 110.0f32.to_radians();
        let fwd = egui::vec2(s.sin(), s.cos());
        let wing = r * 0.55;
        for sign in [-1.0f32, 1.0] {
            let th = sign * 35.0f32.to_radians();
            let w = egui::vec2(
                fwd.x * th.cos() - fwd.y * th.sin(),
                fwd.x * th.sin() + fwd.y * th.cos(),
            );
            ui.painter().line(vec![tip, tip + w * wing], stroke);
        }
    })
}

/// Clear: an X.
fn clear_icon(size: f32) -> egui::Atom<'static> {
    icon_atom(size, |ui, rect, color| {
        let stroke = egui::Stroke::new(1.5, color);
        let inset = rect.height() * 0.28;
        let a = rect.min + egui::vec2(inset, inset);
        let b = rect.max - egui::vec2(inset, inset);
        ui.painter().line(vec![a, b], stroke);
        ui.painter().line(vec![egui::pos2(a.x, b.y), egui::pos2(b.x, a.y)], stroke);
    })
}

/// Load a CJK-capable font from the system so kanji glyphs render.
/// Appended to the Proportional family as a fallback, so Latin text keeps
/// the default font.
fn setup_fonts(ctx: &egui::Context) -> bool {
    let candidates = [
        "C:/Windows/Fonts/NotoSansJP-VF.ttf",
        "C:/Windows/Fonts/msyh.ttc",
        "C:/Windows/Fonts/YuGothM.ttc",
    ];
    let mut fonts = egui::FontDefinitions::default();
    for path in candidates {
        if let Ok(data) = std::fs::read(path) {
            fonts.font_data.insert(
                "cjk".to_owned(),
                std::sync::Arc::new(egui::FontData::from_owned(data)),
            );
            if let Some(fam) = fonts.families.get_mut(&egui::FontFamily::Proportional) {
                fam.push("cjk".to_owned());
            }
            ctx.set_fonts(fonts);
            return true;
        }
    }
    false
}

impl eframe::App for App {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        egui::Panel::top("text_bar").show(ui, |ui| {
            ui.add(
                egui::TextEdit::singleline(&mut self.buffer)
                    .hint_text("Composed text — select all and copy to grab the whole group")
                    .desired_width(f32::INFINITY)
                    .font(egui::FontId::proportional(20.0)),
            );
        });

        egui::Panel::right("candidates")
            .min_size(260.0)
            .show(ui, |ui| {
                ui.heading("Suggestions");

                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(undo_icon(ICON)).min_size(egui::vec2(ICON, ICON))).clicked() {
                        self.strokes.pop();
                        self.current.clear();
                        self.refresh();
                    }
                    if ui.add(egui::Button::new(clear_icon(ICON)).min_size(egui::vec2(ICON, ICON))).clicked() {
                        self.strokes.clear();
                        self.current.clear();
                        self.pool.clear();
                    }
                });
                ui.separator();

                let show = self.pool.len().min(SHOW_LIMIT);
                let mut clicked: Vec<char> = Vec::new();
                egui::ScrollArea::vertical()
                    .auto_shrink([false, false])
                    .show(ui, |ui| {
                        ui.horizontal_wrapped(|ui| {
                            for i in 0..show {
                                let ch = self.pool[i].ch;
                                let button = egui::Button::new(
                                    egui::RichText::new(ch.to_string()).size(22.0),
                                )
                                .min_size(egui::vec2(SQUARE, SQUARE));
                                let resp = if i == 0 {
                                    ui.add(button.fill(egui::Color32::from_rgb(58, 90, 120)))
                                } else {
                                    ui.add(button)
                                };
                                if resp.clicked() {
                                    clicked.push(ch);
                                }
                            }
                        });
                    });
                for ch in clicked {
                    self.copy_to_clipboard(ch);
                    self.buffer.push(ch);
                }
                if !self.font_loaded {
                    ui.label(
                        "Warning: no CJK font found (NotoSansJP/msyh). Kanji glyphs may not render.",
                    );
                }
            });

        egui::CentralPanel::default().show(ui, |ui| {
            let avail = ui.available_size();
            let side = CANVAS.min(avail.x.min(avail.y));
            let rect = egui::Rect::from_min_size(
                ui.min_rect().min + egui::vec2((avail.x - side) * 0.5, (avail.y - side) * 0.5),
                egui::vec2(side, side),
            );

            let painter = ui.painter();
            painter.rect_filled(rect, 0.0, egui::Color32::from_gray(24));
            painter.rect_stroke(
                rect,
                0.0,
                egui::Stroke::new(1.0, egui::Color32::from_gray(120)),
                egui::StrokeKind::Middle,
            );

            // 田字格-style guide: a faint cross dividing the square into four
            // cells, like a kanji practice grid.
            let guide = egui::Stroke::new(1.0, egui::Color32::from_gray(45));
            painter.line(vec![rect.left_center(), rect.right_center()], guide);
            painter.line(vec![rect.center_top(), rect.center_bottom()], guide);

            let id = egui::Id::unique("kanji-canvas");
            let response = ui.interact(rect, id, egui::Sense::drag());

            // `interact_pointer_pos`, not `hover_pos`: egui keeps the drag
            // assigned to the canvas even after the pointer leaves it, while
            // `hover_pos` is None outside the rect. Reading `hover_pos` would
            // drop the stroke on release and let the next stroke overwrite it.
            if let Some(pos) = response.interact_pointer_pos() {
                let p = clamp_to_canvas(pos, rect, side);
                if response.drag_started() {
                    // A previous drag may have been interrupted without a
                    // release; keep it rather than discarding it.
                    if self.current.len() >= 2 {
                        self.strokes.push(std::mem::take(&mut self.current));
                    }
                    self.current = vec![p];
                } else if response.dragged() {
                    let last = self.current.last().copied();
                    match last {
                        Some(l) if (p.0 - l.0).hypot(p.1 - l.1) * side >= MIN_STEP => {
                            self.current.push(p);
                        }
                        Some(_) => {}
                        None => self.current.push(p),
                    }
                }
                if response.drag_stopped() {
                    if self.current.len() >= 2 {
                        self.strokes.push(std::mem::take(&mut self.current));
                        self.recompute();
                    } else {
                        self.current.clear();
                    }
                }
            }

            // Ghost overlay: the strokes the best guess still expects, so the
            // suggestion is visible on the canvas, not just in the list.
            if let Some(best) = self.pool.first() {
                let drawn = self.strokes.len();
                if let Some(ref_strokes) = self.db.strokes_for(best.ch) {
                    let mut ghost: Vec<Vec<egui::Pos2>> = Vec::new();
                    for st in ref_strokes.iter().skip(drawn) {
                        ghost.push(
                            st.iter()
                                .map(|&(x, y)| rect.min + egui::vec2(x * side, y * side))
                                .collect(),
                        );
                    }
                    let ghost_color =
                        egui::Color32::from_rgba_unmultiplied(120, 160, 200, GHOST_ALPHA);
                    for g in ghost {
                        painter.line(g, egui::Stroke::new(2.0, ghost_color));
                    }
                }
            }

            let stroke_color = egui::Color32::from_rgb(40, 40, 60);
            let mut line = Vec::new();
            for st in &self.strokes {
                line.clear();
                line.extend(st.iter().map(|&(x, y)| rect.min + egui::vec2(x * side, y * side)));
                painter.line(line.clone(), egui::Stroke::new(3.0, stroke_color));
            }
            if self.current.len() >= 2 {
                line.clear();
                line.extend(
                    self.current
                        .iter()
                        .map(|&(x, y)| rect.min + egui::vec2(x * side, y * side)),
                );
                painter.line(line, egui::Stroke::new(3.0, stroke_color));
            }

            // Stroke-number guides like an IME pad: faint numbers at the start
            // of each drawn stroke.
            for (i, st) in self.strokes.iter().enumerate() {
                if let Some(&(x, y)) = st.first() {
                    painter.text(
                        rect.min + egui::vec2(x * side, y * side),
                        egui::Align2::CENTER_CENTER,
                        (i + 1).to_string(),
                        egui::FontId::proportional(11.0),
                        egui::Color32::from_gray(140),
                    );
                }
            }
        });
    }
}

fn main() -> eframe::Result {
    let opts = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default().with_inner_size([900.0, 640.0]),
        ..Default::default()
    };
    eframe::run_native(
        "Kanji Pad",
        opts,
        Box::new(|cc| Ok(Box::new(App::new(cc)))),
    )
}
